const statusNames={draft:['مسودة','Draft'],in_review:['قيد الاعتماد','In review'],active:['نشط','Active'],changes_requested:['مطلوب تعديل','Changes requested'],rejected:['مرفوض','Rejected']};
const fieldNames={field:['المجال الوظيفي','Field'],seniority:['المستوى المطلوب','Seniority'],title:['المسمى الوظيفي','Position title'],businessNeed:['المبرر التجاري','Business need'],alternatives:['البدائل التي تمت دراستها','Alternatives considered'],successMeasures:['مؤشرات نجاح المنصب','Success measures'],purpose:['هدف المنصب','Position purpose'],responsibilities:['المسؤوليات — ثلاث مهام على الأقل','Responsibilities — at least three'],team:['الفريق ونطاق الإشراف','Team and span of control'],budget:['نطاق الميزانية','Budget scope'],authority:['صلاحيات اتخاذ القرار','Decision authority'],impact:['نطاق الأثر','Impact'],stakeholders:['أصحاب العلاقة','Stakeholders'],qualifications:['المؤهلات المطلوبة','Qualifications'],experience:['الخبرة المطلوبة','Experience'],skills:['المهارات الفنية','Technical skills'],behaviors:['الجدارات السلوكية','Behavioral competencies'],manager:['المدير المباشر','Reporting manager'],constraints:['محددات تنظيمية وتشغيلية','Operational and regulatory constraints'],mappingJustification:['مبرر الترميز المؤقت','Provisional-code justification'],provisionalParent:['رمز الوحدة الأب المقترح','Proposed parent unit code']};
const button=(id,label,primary=false)=>'<button type="button" id="ent-'+id+'" class="button button-'+(primary?'primary':'outline')+'">'+label+'</button>';
